const DEFAULT_PLACE: Place = { lat: 12.1364, lng: -86.2514, address: "Managua, Nicaragua" };
const gpsMeters = (a: Pick<Place, "lat" | "lng">, b: Pick<Place, "lat" | "lng">) => {
  const radius = 6_371_000; const dLat = (b.lat - a.lat) * Math.PI / 180; const dLng = (b.lng - a.lng) * Math.PI / 180;
  const value = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * Math.PI / 180) * Math.cos(b.lat * Math.PI / 180) * Math.sin(dLng / 2) ** 2;
  return 2 * radius * Math.atan2(Math.sqrt(value), Math.sqrt(1 - value));
};
const safeHeading = (heading: number | null) => heading !== null && Number.isFinite(heading) && heading >= 0 && heading < 360 ? heading : undefined;
const ACTIVE = ["REQUESTED", "ACCEPTED", "RIDER_ON_THE_WAY", "RIDER_ARRIVED", "IN_PROGRESS"];
const TRIP_STATUS_LABELS: Record<string, string> = {
  REQUESTED: "Buscando rider", ACCEPTED: "Rider asignado", RIDER_ON_THE_WAY: "Rider en camino",
  RIDER_ARRIVED: "Rider llegó", IN_PROGRESS: "Viaje en curso", COMPLETED: "Finalizado",
  CANCELED_BY_CLIENT: "Cancelado por pasajero", CANCELED_BY_RIDER: "Cancelado por rider", CANCELLED: "Cancelado"
};
function tripStatusLabel(status?: string) { return TRIP_STATUS_LABELS[status || ""] || "Actualizando viaje"; }
function clientActivationLabel(status?: string) { const labels: Record<string, string> = { ACTIVE: "Cuenta activa", SEMI_ACTIVE: "Cuenta activa", REGISTERED: "Registro completado", VERIFICATION_PENDING: "Verificación en proceso", REQUIRES_CORRECTION: "Requiere actualización", SUSPENDED: "Cuenta suspendida" }; return labels[status || ""] || "Cuenta activa"; }
function isPlaceholderAddress(address?: string | null) { return !address || /^(ubicaci[oó]n actual|tu ubicaci[oó]n|punto seleccionado en el mapa|ubicaci[oó]n seleccionada)$/i.test(address.trim()); }
function displayAddress(address?: string | null) { if (isPlaceholderAddress(address)) return "Dirección por confirmar"; const parts = (address || "").split(",").map(part => part.trim()).filter(part => part && !/^nicaragua$/i.test(part) && !/^centroam[eé]rica$/i.test(part)); return parts.slice(0, 3).join(", ") || "Dirección por confirmar"; }
async function resolvePlace(point: Pick<Place, "lat" | "lng">): Promise<Place> {
  try {
    const [native] = await Location.reverseGeocodeAsync({ latitude: point.lat, longitude: point.lng });
    const details = native as { name?: string | null; street?: string | null; streetNumber?: string | null; district?: string | null; city?: string | null; subregion?: string | null; region?: string | null } | undefined;
    const street = [details?.streetNumber, details?.street].filter(Boolean).join(" ");
    const pieces = [details?.name, street, details?.district, details?.city || details?.subregion, details?.region].filter((part): part is string => Boolean(part && part.trim()));
    const address = [...new Set(pieces.map(part => part.trim()))].slice(0, 3).join(", ");
    if (address) return { ...point, address };
  } catch { /* Usa la API como respaldo cuando el proveedor local no responda. */ }
  return reverseGeocode(point.lat, point.lng);
}
type Tab = "home" | "trip" | "places" | "history" | "account" | "work" | "earnings";

