  const cancel = () => { if (!active) return; Alert.alert("Cancelar por incidencia", "El viaje se liberará nuevamente si aún no iniciaste la ruta. ¿Continuar?", [{ text: "No", style: "cancel" }, { text: "Cancelar viaje", style: "destructive", onPress: () => void api(`/trips/${active.id}/cancel`, { method: "POST", body: JSON.stringify({ reason: "Incidencia reportada por rider" }) }).then(() => onActive(null)).catch(error => onMessage((error as Error).message)) }]); };
